<?php
namespace App\Http\Controllers;
use App\Models\{User,Apprentice,StaffHandoverBatch as Batch};
use App\Support\{StaffHandover as Handover,LearningAccess};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
class StaffHandoverController extends Controller {
 private function manager(Request $r):void {abort_unless(LearningAccess::manager($r->user()),403);}
 private function view(string $name,array $data=[]) {return response()->view('staff-handovers.'.$name,$data)->header('Cache-Control','no-store, private')->header('Referrer-Policy','no-referrer');}
 public function index(Request $r) {$this->manager($r);$d=$r->validate(['state'=>['nullable','in:all,Pending,Applied,Rejected,Withdrawn'],'page'=>['nullable','integer','min:1']]);$state=$d['state']??'all';$batches=Batch::when($state!=='all',fn($q)=>$q->where('state',$state))->orderByDesc('created_at')->orderByDesc('id')->paginate(20)->withQueryString();return $this->view('index',compact('batches','state'));}
 public function workload(Request $r) {$this->manager($r);$r->validate(['search'=>['nullable','string','max:100']]);$search=trim($r->input('search',''));$snapshot=Handover::workload($r->user());$snapshot['rows']=array_filter($snapshot['rows'],fn($x)=>$search===''||str_contains(mb_strtolower($x['user']->name),mb_strtolower($search)));return $this->view('workload',compact('snapshot','search'));}
 public function create(Request $r) {$this->manager($r);$d=$r->validate(['slot'=>['nullable',Rule::in(array_keys(Handover::SLOTS))],'from'=>['nullable','integer','min:0'],'search'=>['nullable','string','max:100'],'page'=>['nullable','integer','min:1']]);$slot=$d['slot']??'tutor';$from=(int)($d['from']??0);$search=trim($d['search']??'');$field=$slot.'_id';$q=Apprentice::where($field,$from?:null);if($search!==''){$needle='%'.str_replace(['!','%','_'],['!!','!%','!_'],mb_strtolower($search)).'%';$q->where(fn($q)=>$q->whereRaw("LOWER(reference) LIKE ? ESCAPE '!'",[$needle])->orWhereRaw("LOWER(first_name) LIKE ? ESCAPE '!'",[$needle])->orWhereRaw("LOWER(last_name) LIKE ? ESCAPE '!'",[$needle]));}$people=$q->orderBy('last_name')->orderBy('id')->paginate(50)->withQueryString();$staff=User::orderBy('name')->orderBy('id')->get(['id','name','role','active']);$targets=User::orderBy('name')->orderBy('id')->get()->filter(fn($u)=>Handover::eligible($u,$slot));return $this->view('create',compact('slot','from','search','people','staff','targets'));}
 public function prepare(Request $r) {$this->manager($r);$d=$r->validate(['slot'=>['required',Rule::in(array_keys(Handover::SLOTS))],'from'=>['required','integer','min:0'],'target'=>['required','integer','min:1'],'apprentices'=>['required','array','min:1','max:100'],'apprentices.*'=>['required','integer','min:1','distinct'],'reason'=>['required','string','max:2000'],'confirmed'=>['accepted']]);$b=Handover::prepare($r->user(),(int)$r->session()->get('auth_version'),$d['slot'],(int)$d['from']?:null,(int)$d['target'],array_map('intval',$d['apprentices']),$d['reason']);return to_route('staff-handovers.show',$b)->with('status','Exact preview saved. No apprentice assignment changed; a different manager must check and apply.');}
 public function show(Request $r,Batch $handover) {$this->manager($r);abort_unless(Handover::intact($handover),409,'Handover evidence cannot be verified.');$target=User::find($handover->target_user_id);$scope=$target?Handover::incomingScope($handover,$target):['rows'=>[],'hash'=>null];return $this->view('show',['handover'=>$handover,'source'=>$handover->source,'fresh'=>Handover::fresh($handover),'applied'=>Handover::applied($handover),'scope'=>$scope,'ack'=>$target?Handover::acknowledgement($handover,$target,$scope):null,'events'=>DB::table('staff_handover_events')->where('batch_id',$handover->id)->orderBy('id')->get(['event','actor_id','record_version','created_at'])]);}
 public function decide(Request $r,Batch $handover) {$this->manager($r);$d=$r->validate(['version'=>['required','integer','min:1'],'decision'=>['required','in:apply,reject,withdraw'],'note'=>['required','string','max:2000'],'confirmed'=>['accepted']]);Handover::decide($r->user(),(int)$r->session()->get('auth_version'),$handover,(int)$d['version'],$d['decision'],$d['note']);return back()->with('status','Handover decision saved. No automatic external messages, group transfer or historic sign-off changes.');}
 public function report(Request $r,Batch $handover) {$this->manager($r);abort_unless(Handover::intact($handover),409);$s=$handover->source;return response()->json(['batch_id'=>$handover->id,'state'=>$handover->state,'applied_proof_verified'=>Handover::applied($handover),'slot'=>$handover->slot,'from_user_id'=>$handover->from_user_id,'target_user_id'=>$handover->target_user_id,'created_by'=>$handover->created_by,'reviewed_by'=>$handover->reviewed_by,'reviewed_at'=>$handover->reviewed_at?->toIso8601String(),'rows'=>array_map(fn($row)=>['apprentice_id'=>$row['id'],'reference'=>$row['reference'],'preview_version'=>$row['version']],$s['rows']),'private_notes_and_identity_seals_exported'=>false,'automatic_messages_sent'=>false,'production_approved'=>false],200,['Content-Disposition'=>'attachment; filename="GTA-Staff-Handover.json"','Cache-Control'=>'no-store, private','Referrer-Policy'=>'no-referrer']);}
 public function incoming(Request $r) {$u=$r->user();abort_unless(Handover::recipientAllowed($u),403);$r->validate(['page'=>['nullable','integer','min:1']]);$batches=Batch::where('target_user_id',$u->id)->where('state','Applied')->orderByDesc('reviewed_at')->orderByDesc('id')->paginate(20);$scopes=[];$acks=[];foreach($batches as$b){$scopes[$b->id]=Handover::incomingScope($b,$u);$acks[$b->id]=Handover::acknowledgement($b,$u,$scopes[$b->id]);}return $this->view('incoming',compact('batches','scopes','acks'));}
 public function acknowledge(Request $r,Batch $handover) {abort_unless(Handover::recipientAllowed($r->user()),403);$d=$r->validate(['version'=>['required','integer','min:0'],'scope_hash'=>['required','regex:/^[a-f0-9]{64}$/D'],'confirmed'=>['required','boolean']]);Handover::acknowledge($r->user(),(int)$r->session()->get('auth_version'),$handover,(int)$d['version'],$d['scope_hash'],$r->boolean('confirmed'));return back()->with('status','Acknowledgement saved for the currently visible assignment scope only. No learner work or review was completed.');}
}
